/**
 * Very lightweight German stemmer. Removes common suffixes.
 */
function stemGerman(word: string): string {
  // Remove 'n', 'e', 'em', 'er', 'es' if word length > 4
  if (word.length <= 4) return word;

  let stem = word;
  if (stem.endsWith("ern") || stem.endsWith("ers")) stem = stem.slice(0, -3);
  else if (stem.endsWith("en") || stem.endsWith("er") || stem.endsWith("es") || stem.endsWith("em")) stem = stem.slice(0, -2);
  else if (stem.endsWith("e") || stem.endsWith("n")) stem = stem.slice(0, -1);

  // Basic umlaut normalization for the stem: büch -> buch
  return stem
    .replace(/ä/g, "a")
    .replace(/ö/g, "o")
    .replace(/ü/g, "u")
    .replace(/ß/g, "ss");
}

