  it("strips punctuation", () => {
    // "please" -> stem: "pleas" (e removed)
    expect(extractQueryTerms("Karpathy's videos, please!")).toContain("karpathy");
    expect(extractQueryTerms("Karpathy's videos, please!")).toContain("videos");
