import type { Entity, Concept, SourceRecord } from "../core/types.js";

function todayIso(): string {
  return new Date().toISOString().slice(0, 10);
}

export function entityFrontmatter(
  entity: Entity,
  today?: string,
): Record<string, unknown> {
