  return {
    typ: "entität",
    "entitäts-typ": entity.type,
    name: entity.name,
    aliases: [...entity.aliases],
    tags: ["llm-wiki/entity", `llm-wiki/entity/${entity.type}`],
    "quellen-anzahl": entity.sources.length,
    "aktualisierungs-datum": today,
    cssclasses: [],
  };
