    aliases: [],
    tags: ["llm-wiki/concept"],
    "quellen-anzahl": concept.sources.length,
    "aktualisierungs-datum": today,
    cssclasses: [],
  };
}

export function sourceFrontmatter(
  source: SourceRecord,
): Record<string, unknown> {
  return {
    typ: "quelle",
