const CONNECTION_TYPE_LABELS: Record<string, string> = {
  influences: "beeinflusst",
  uses: "verwendet",
  critiques: "kritisiert",
  extends: "erweitert",
  "part-of": "Teil von",
  "created-by": "erstellt von",
  "related-to": "verknüpft mit",
  "applies-to": "bezieht sich auf",
  "contrasts-with": "steht im Kontrast zu",
};

export function renderEntityPage(
  entity: Entity,
  connections: Connection[],
  today?: string,
): string {
  const fm = entityFrontmatter(entity, today);
  const outgoing = connections.filter((c) => c.from === entity.id);
  const incoming = connections.filter((c) => c.to === entity.id);

  const lines: string[] = [serializeFrontmatter(fm), "", `# ${entity.name}`, ""];

  if (entity.facts.length > 0) {
    lines.push("## Fakten", "");
    for (const f of entity.facts) {
      lines.push(`- ${f}`);
    }
    lines.push("");
  }

  if (outgoing.length > 0 || incoming.length > 0) {
    lines.push("## Verbindungen", "");
    for (const c of outgoing) {
      const typeLabel = CONNECTION_TYPE_LABELS[c.type] ?? c.type;
      lines.push(`- [[${c.to}]] *(${typeLabel})*`);
    }
    for (const c of incoming) {
      const typeLabel = CONNECTION_TYPE_LABELS[c.type] ?? c.type;
      lines.push(`- [[${c.from}]] *(${typeLabel})*`);
    }
    lines.push("");
  }

  if (entity.sources.length > 0) {
    lines.push("## Quellen", "");
    for (const s of entity.sources) {
      lines.push(`- [[${s}]]`);
    }
    lines.push("");
  }

  return lines.join("\n");
}

import type { Concept } from "../core/types.js";
import { makeId } from "../core/ids.js";
import { conceptFrontmatter, serializeFrontmatter } from "./frontmatter.js";

export function renderConceptPage(concept: Concept, today?: string): string {
  const fm = conceptFrontmatter(concept, today);
  const lines: string[] = [
    serializeFrontmatter(fm),
    "",
    `# ${concept.name}`,
    "",
  ];

  if (concept.definition) {
    lines.push(concept.definition, "");
  }

  if (concept.related.length > 0) {
    lines.push("## Verwandte Begriffe", "");
    for (const r of concept.related) {
      lines.push(`- [[${makeId(r)}|${r}]]`);
    }
    lines.push("");
  }

  if (concept.sources.length > 0) {
    lines.push("## Quellen", "");
    for (const s of concept.sources) {
      lines.push(`- [[${s}]]`);
    }
    lines.push("");
  }

  return lines.join("\n");
}

import type { Concept, Entity, SourceRecord } from "../core/types.js";
import { sourceFrontmatter, serializeFrontmatter } from "./frontmatter.js";

export function renderSourcePage(
  source: SourceRecord,
  entities: Entity[],
  concepts: Concept[],
): string {
  const fm = sourceFrontmatter(source);
  const lines: string[] = [
    serializeFrontmatter(fm),
    "",
    `# ${source.id}`,
    "",
  ];

  if (source.summary) {
    lines.push(source.summary, "");
  }

  if (entities.length > 0) {
    lines.push("## Entitäten", "");
    for (const e of entities) {
      lines.push(`- [[${e.id}|${e.name}]]`);
    }
    lines.push("");
  }

  if (concepts.length > 0) {
    lines.push("## Konzepte", "");
    for (const c of concepts) {
      lines.push(`- [[${c.id}|${c.name}]]`);
    }
    lines.push("");
  }

  return lines.join("\n");
}

import type { Entity, Concept, SourceRecord } from "../core/types.js";

function todayIso(): string {
  return new Date().toISOString().slice(0, 10);
}

export function entityFrontmatter(
  entity: Entity,
  today = todayIso(),
): Record<string, unknown> {
  return {
    typ: "entität",
    "entitäts-typ": entity.type,
    name: entity.name,
    aliases: [...entity.aliases],
    tags: ["llm-wiki/entity", `llm-wiki/entity/${entity.type}`],
    "quellen-anzahl": entity.sources.length,
    "aktualisiert": today,
    cssclasses: [],
  };
}

export function conceptFrontmatter(
  concept: Concept,
  today = todayIso(),
): Record<string, unknown> {
  return {
    typ: "konzept",
    name: concept.name,
    aliases: [],
    tags: ["llm-wiki/concept"],
    "quellen-anzahl": concept.sources.length,
    "aktualisiert": today,
    cssclasses: [],
  };
}

export function sourceFrontmatter(
  source: SourceRecord,
): Record<string, unknown> {
  return {
    typ: "quelle",
    herkunft: source.origin,
    datum: source.date,
    tags: ["llm-wiki/source"],
    aliases: [],
    cssclasses: [],
  };
}

function yamlScalar(value: unknown): string {
  if (typeof value === "string") {
    // Quote if value contains YAML-unsafe characters
    if (/[:{}[\],#&*!|>'"%@`]/.test(value) || value.trim() !== value) {
      return `"${value.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
    }
    return value;
  }
  return String(value);
}

/**
 * Serialize a frontmatter object to a YAML block (including --- delimiters).
 * Handles strings, numbers, booleans, and arrays of primitives.
 */
export function serializeFrontmatter(fm: Record<string, unknown>): string {
  const lines = ["---"];
  for (const [key, value] of Object.entries(fm)) {
    if (Array.isArray(value)) {
      if (value.length === 0) {
        lines.push(`${key}: []`);
      } else {
        lines.push(`${key}:`);
        for (const item of value) {
          lines.push(`  - ${yamlScalar(item)}`);
        }
      }
    } else {
      lines.push(`${key}: ${yamlScalar(value)}`);
    }
  }
  lines.push("---");
  return lines.join("\n") + "\n";
}

