  for (const p of LIST_PATTERNS) if (p.test(text)) return "list_category";
  for (const p of RELATIONAL_PATTERNS) if (p.test(text)) return "relational";
  for (const p of ENTITY_PATTERNS) if (p.test(text)) return "entity_lookup";
  return "conceptual";
}

