      responses: ["answer text"],
      chunked: true,
    });
    const states: QueryControllerState[] = [];
    const chunks: string[] = [];
    const ctrl = new QueryController({
      kb,
      provider,
      model: "test",
      onState: (s) => states.push(s),
      onChunk: (t) => chunks.push(t),
      onContext: () => {},
    });
    await ctrl.run("who is Alan Watts");
