      createdAt: 0,
      updatedAt: 0,
      folder: "",
      model: "test",
      turns: [],
    };
  }

  function buildChatWithOneTurn(): Chat {
    return {
      id: "c1",
      title: "",
      createdAt: 0,
      updatedAt: 0,
      folder: "",
      model: "test",
